    ws.onmessage = (event) => {
      const msg = JSON.parse(event.data);
      if (msg.type === 'chat') add(`${msg.from}: ${msg.text}`);
      else if (msg.type === 'system') add(msg.text, 'system');
      else if (msg.type === 'error') add(msg.text, 'system');
      else if (msg.type === 'users') document.getElementById('users').textContent = 'Online: ' + msg.users.join(', ');
    };
    ws.onclose = () => add('Disconnected', 'system');

    document.getElementById('form').onsubmit = (e) => {
      e.preventDefault();
