import fs from 'node:fs/promises';
import { setTimeout as sleep } from 'node:timers/promises';
import * as cheerio from 'cheerio';

const START = process.argv[2] ?? 'https://books.toscrape.com/';
const MAX_PAGES = Number(process.argv[3] ?? 2);
const DELAY_MS = 500;                                    // be polite: pause between requests

async function fetchHtml(url, retries = 2) {
  for (let attempt = 0; ; attempt++) {
    try {
      const res = await fetch(url, {
        headers: { 'User-Agent': 'learn-node-scraper/1.0 (+student project)' },
        signal: AbortSignal.timeout(10_000),
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return await res.text();
    } catch (err) {
      if (attempt >= retries) throw err;
      await sleep(1000 * (attempt + 1));
    }
  }
}

function parsePage(html, pageUrl) {
  const $ = cheerio.load(html);
  const books = $('article.product_pod').map((_, el) => {
    const card = $(el);
    return {
      title: card.find('h3 a').attr('title'),
      price: Number(card.find('.price_color').text().replace(/[^\d.]/g, '')),
      inStock: card.find('.availability').text().includes('In stock'),
      rating: card.find('p.star-rating').attr('class').replace('star-rating', '').trim(),
      url: new URL(card.find('h3 a').attr('href'), pageUrl).href,   // resolve relative links
    };
  }).get();
  const next = $('li.next a').attr('href');
  return { books, nextUrl: next ? new URL(next, pageUrl).href : null };
}

const all = [];
let url = START;
for (let page = 1; url && page <= MAX_PAGES; page++) {
