// ---- cron.js ----
// Parse one cron field such as "*", "*/15", "1-5", "1,15,30" into a Set of numbers
function parseField(field, min, max) {
  const values = new Set();
  for (const part of field.split(',')) {
    const [range, stepText] = part.split('/');
    const step = stepText ? Number(stepText) : 1;
    let from, to;
    if (range === '*') [from, to] = [min, max];
    else if (range.includes('-')) [from, to] = range.split('-').map(Number);
    else [from, to] = stepText ? [Number(range), max] : [Number(range), Number(range)];

    if ([from, to, step].some(Number.isNaN) || step < 1 || from < min || to > max || from > to) {
      throw new Error(`Invalid cron field "${field}"`);
    }
    for (let v = from; v <= to; v += step) values.add(v);
  }
  return values;
}

export function parseCron(expression) {
  const parts = expression.trim().split(/\s+/);
  if (parts.length !== 5) throw new Error('Cron needs 5 fields: minute hour day month weekday');
  const [minute, hour, day, month, weekday] = parts;
  return {
    minute: parseField(minute, 0, 59),
    hour: parseField(hour, 0, 23),
    day: parseField(day, 1, 31),
    month: parseField(month, 1, 12),
    weekday: parseField(weekday, 0, 6),             // 0 = Sunday
  };
}

export function matches(schedule, date) {
  return schedule.minute.has(date.getMinutes())
    && schedule.hour.has(date.getHours())
    && schedule.day.has(date.getDate())
    && schedule.month.has(date.getMonth() + 1)
    && schedule.weekday.has(date.getDay());
}

export class Scheduler {
  #jobs = [];
  #timer = null;

  add(name, expression, task) {
    this.#jobs.push({ name, schedule: parseCron(expression), task, running: false });
    return this;
  }

  start() {
    const tick = () => {
      const now = new Date();
      for (const job of this.#jobs) {
        if (!matches(job.schedule, now)) continue;
        if (job.running) { console.warn(`[${job.name}] skipped: previous run still active`); continue; }
        this.#run(job);
      }
      // schedule the next tick at the start of the next minute (no drift)
      this.#timer = setTimeout(tick, 60_000 - (Date.now() % 60_000));
    };
    this.#timer = setTimeout(tick, 60_000 - (Date.now() % 60_000));
    return this;
  }

  async #run(job) {
    job.running = true;
    const started = Date.now();
    try {
      await job.task();
      console.log(`[${job.name}] finished in ${Date.now() - started} ms`);
    } catch (err) {
      console.error(`[${job.name}] failed:`, err.message);     // one bad job never stops the scheduler
    } finally {
      job.running = false;
    }
  }

  stop() { clearTimeout(this.#timer); }
}

