import crypto from 'node:crypto';
import express from 'express';
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';

const PORT = process.env.PORT ?? 3000;
const ACCESS_SECRET = process.env.ACCESS_SECRET ?? crypto.randomBytes(32).toString('hex'); // set it in .env for real use
const ACCESS_TTL = '15m';
const REFRESH_TTL_MS = 7 * 24 * 3600 * 1000;

// ---- "database" (replace with a real one) ----
const users = new Map();           // email -> { id, email, name, role, passwordHash }
const refreshTokens = new Map();   // sha256(token) -> { userId, expiresAt }

const sha256 = (s) => crypto.createHash('sha256').update(s).digest('hex');
const publicUser = ({ id, email, name, role }) => ({ id, email, name, role });

class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}

function signAccessToken(user) {
  return jwt.sign({ sub: user.id, role: user.role }, ACCESS_SECRET, { expiresIn: ACCESS_TTL, algorithm: 'HS256' });
}

function issueRefreshToken(userId) {
  const token = crypto.randomBytes(48).toString('base64url'); // opaque random token
  refreshTokens.set(sha256(token), { userId, expiresAt: Date.now() + REFRESH_TTL_MS });
  return token; // only the hash is stored
}

function setRefreshCookie(res, token) {
  res.cookie('refresh_token', token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    path: '/auth',
    maxAge: REFRESH_TTL_MS,
  });
}

const readCookie = (req, name) =>
  req.headers.cookie?.split(';').map((c) => c.trim().split('=')).find(([k]) => k === name)?.[1];

function requireAuth(req, res, next) {
  const header = req.headers.authorization ?? '';
  if (!header.startsWith('Bearer ')) return next(new HttpError(401, 'Missing token'));
  try {
    req.auth = jwt.verify(header.slice(7), ACCESS_SECRET, { algorithms: ['HS256'] });
    next();
  } catch (err) {
    next(new HttpError(401, err.name === 'TokenExpiredError' ? 'Token expired' : 'Invalid token'));
  }
}

const requireRole = (role) => (req, res, next) =>
  req.auth.role === role ? next() : next(new HttpError(403, 'Forbidden'));

const app = express();
app.use(express.json({ limit: '10kb' }));

app.post('/auth/register', async (req, res) => {
  const { email, password, name } = req.body ?? {};
  if (typeof email !== 'string' || !/^\S+@\S+\.\S+$/.test(email)) throw new HttpError(422, 'Valid email required');
  if (typeof password !== 'string' || password.length < 8) throw new HttpError(422, 'Password must be at least 8 characters');
  if (users.has(email.toLowerCase())) throw new HttpError(409, 'Email already registered');

  const user = {
    id: crypto.randomUUID(),
    email: email.toLowerCase(),
    name: String(name ?? '').slice(0, 50),
    role: users.size === 0 ? 'admin' : 'user', // first user becomes admin (demo only)
    passwordHash: await bcrypt.hash(password, 12),
  };
  users.set(user.email, user);
  res.status(201).json(publicUser(user));
});

const DUMMY_HASH = bcrypt.hashSync('not-a-real-password', 12);

app.post('/auth/login', async (req, res) => {
  const { email = '', password = '' } = req.body ?? {};
  const user = users.get(String(email).toLowerCase());
  const ok = await bcrypt.compare(String(password), user?.passwordHash ?? DUMMY_HASH);
  if (!user || !ok) throw new HttpError(401, 'Invalid credentials'); // same message for both cases

  setRefreshCookie(res, issueRefreshToken(user.id));
  res.json({ accessToken: signAccessToken(user), user: publicUser(user) });
});

app.post('/auth/refresh', (req, res) => {
  const token = readCookie(req, 'refresh_token');
  const record = token && refreshTokens.get(sha256(token));
  if (!record || record.expiresAt < Date.now()) throw new HttpError(401, 'Invalid refresh token');

  refreshTokens.delete(sha256(token)); // rotation: each refresh token works only once
  const user = [...users.values()].find((u) => u.id === record.userId);
  setRefreshCookie(res, issueRefreshToken(user.id));
  res.json({ accessToken: signAccessToken(user) });
});

app.post('/auth/logout', (req, res) => {
  const token = readCookie(req, 'refresh_token');
  if (token) refreshTokens.delete(sha256(token));
  res.clearCookie('refresh_token', { path: '/auth' }).status(204).end();
});

app.get('/me', requireAuth, (req, res) => {
  const user = [...users.values()].find((u) => u.id === req.auth.sub);
  res.json(publicUser(user));
});

app.get('/admin/users', requireAuth, requireRole('admin'), (req, res) => {
  res.json([...users.values()].map(publicUser));
});

app.use((req, res) => res.status(404).json({ error: 'Not found' }));

app.use((err, req, res, next) => {
  const status = err.status ?? (err.type === 'entity.parse.failed' ? 400 : 500);
  if (status === 500) console.error(err);
  res.status(status).json({ error: status === 500 ? 'Internal error' : err.message });
});

app.listen(PORT, () => console.log(`Auth service on http://localhost:${PORT}`));

